  ('e38265ce-8879-4892-84f2-1a86e1307fde', 'meridian-automatic-40', 'Meridian Automatic 40', 'Meridian', 'A 40mm automatic with a sector dial and a movement worth servicing thirty years from now. Worn thin under a cuff, heavy enough to notice.', 'watches', 1850000, NULL, array['https://images.unsplash.com/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1622434641406-a158123450f9?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1524592094714-0f0654e20314?auto=format&fit=crop&w=1400&q=80', 'https://images.unsplash.com/photo-1548171915-e79a380a2a4b?auto=format&fit=crop&w=1400&q=80']::text[], '[{"label":"Movement","value":"Automatic · 38h reserve"},{"label":"Case","value":"40mm stainless steel"},{"label":"Crystal","value":"Sapphire, anti-reflective"},{"label":"Water resistance","value":"50m"}]'::jsonb, array['new']::text[], true, NULL, false, true, '2026-09-12T09:00:00Z'),
